<?php
declare(strict_types=1);
$env=[];foreach(file(__DIR__.'/../.env',FILE_IGNORE_NEW_LINES|FILE_SKIP_EMPTY_LINES)?:[] as $line){$line=trim($line);if($line===''||$line[0]==='#'||!str_contains($line,'='))continue;[$k,$v]=explode('=',$line,2);$env[trim($k)]=trim(trim($v),"\"'");}
function c(array $e,string $p,string $db):PDO{return new PDO('mysql:host='.$e[$p.'_DB_HOST'].';port='.$e[$p.'_DB_PORT'].';dbname='.$db.';charset=utf8mb4',$e[$p.'_DB_USERNAME'],$e[$p.'_DB_PASSWORD'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);}
function call(PDO $p,string $table,array $filters,int $limit=10):array{$s=$p->prepare('CALL sp_crud_select(:tabela,:filtros,NULL,:limite,0)');$s->execute(['tabela'=>$table,'filtros'=>json_encode($filters,JSON_UNESCAPED_UNICODE),'limite'=>$limit]);$rows=$s->fetchAll(PDO::FETCH_ASSOC);$s->closeCursor();return $rows;}
$central=c($env,'GUNIVERSAL',$env['GUNIVERSAL_DB_DATABASE']??'guniversal_dbp');$target=c($env,'GPT','gatlas_dbp');$result=[];try{$central->exec("UPDATE empresa SET status='ATIVA' WHERE codigo='ATLAS' AND banco_dados='gatlas_dbp'");$companies=call($central,'empresa',['status'=>'ATIVA'],1000);$atlas=array_values(array_filter($companies,fn($x)=>strtoupper((string)($x['codigo']??''))==='ATLAS'));$user=call($target,'usuarios',['userid'=>'admin'],1);$result=['central_resolveu_atlas'=>count($atlas)===1,'banco_resolvido'=>$atlas[0]['banco_dados']??null,'admin_encontrado'=>count($user)===1,'admin_ativo'=>(bool)($user[0]['ativo']??false),'senha_usa_hash'=>(int)($user[0]['senha_usa_hash']??-1)];}finally{$central->exec("UPDATE empresa SET status='INATIVA' WHERE codigo='ATLAS' AND banco_dados='gatlas_dbp'");}$result['status_final']='INATIVA';echo json_encode($result,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE).PHP_EOL;
